pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address actor, address newOwner) public {
        address admin = msg.sender; // deployer of c in setUp is this test contract's admin = test contract
        admin = address(this);      // C recorded admin = msg.sender in its constructor = this test contract
        vm.assume(actor != admin);
        vm.assume(newOwner != actor);

        // Admin legitimately transfers ownership to `actor`.
        vm.prank(admin);
        c.setOwner(actor);

        // A non-owner, non-admin caller must NEVER be able to change owner.
        vm.prank(actor);
        try c.setOwner(newOwner) {
            // mutant allows this
        } catch {
            // reference reverts here
        }

        assertTrue(c.owner() == actor, "non-admin caller must not be able to change owner");
    }
}

