pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address x) public {
        vm.prank(address(this));
        bool ok1;
        try c.setOwner(x) { ok1 = true; } catch { ok1 = false; }
        if (!ok1) return; // e.g. x = type(uint160).max overflows only in mutant; skip
        address y = c.owner();
        vm.prank(address(this));
        bool ok2;
        try c.setOwner(y) { ok2 = true; } catch { ok2 = false; }
        if (ok2) {
            assertTrue(c.owner() == y, "owner must be a fixed point of setOwner");
        } else {
            assertTrue(false, "re-setting stored owner must always succeed on correct contract");
        }
    }
}

